"""FritzBox Router: OpenBridge adapter (generated by `openbridge partner new`, transport filled in).

Reads an AVM FRITZ!Box over its local TR-064 SOAP API (port 49000): uptime, WAN state, known hosts,
Wi-Fi clients, model and firmware. Like the OpenWrt and Freebox integrations, this adapter is read-only
by policy: only Get actions exist here, so nothing on the router can change.

Every value is read from the device; anything unrecognized fails closed with FritzboxRouterError.

Status: emulator only. Record real-hardware runs in docs/DEVICE_EVIDENCE.json before claiming support.
"""
import urllib.error
import urllib.request
import xml.etree.ElementTree as ET

READ = {'uptime': 's', 'wan': '', 'hosts': '', 'wifi_clients': '', 'model': '', 'firmware': ''}
WRITABLE = {}
COMMANDS = {}
POLICY = {('*', '*'): 'Router configuration is read-only in OpenBridge.',
          ('firmware', '*'): 'Firmware is never changed by OpenBridge.'}

TIMEOUT_S = 5
MAX_BODY = 262144
PORT = 49000

# service -> control URL (AVM defaults; verified against tr64desc.xml on real boxes).
SERVICES = {'DeviceInfo': '/upnp/control/deviceinfo',
            'Hosts': '/upnp/control/hosts',
            'WANIPConnection': '/upnp/control/wanipconnection1',
            'WLANConfiguration': '/upnp/control/wlanconfig1'}


class FritzboxRouterBlocked(PermissionError):
    """Refused before anything was sent."""


class FritzboxRouterError(OSError):
    """The router could not be reached or answered something unrecognized."""


def _host_allowed(host):
    from src.fabric import netguard
    return netguard.local_host(host, bare_names=True, extra_names=('fritz.box',), extra_suffixes=('.fritz.box',))


def _local(tag):
    return tag.rsplit('}', 1)[-1]


def _find(doc, *names):
    """First element matching any of the names, namespace-agnostic, depth-first."""
    for el in doc.iter():
        if _local(el.tag) in names:
            return el
    return None


class FritzboxRouterTransport:
    """Minimal TR-064 client. Only Get actions exist; there is no write method."""

    def __init__(self, host, username, password, port=PORT, timeout=TIMEOUT_S):
        if not _host_allowed(host):
            raise FritzboxRouterBlocked('refusing non-local router host %r' % (host,))
        if not username or not password:
            raise FritzboxRouterBlocked('TR-064 needs a FRITZ!Box user and password (create one in the box UI)')
        self.base = 'http://%s:%d' % (host.strip(), int(port))
        self.timeout = timeout
        mgr = urllib.request.HTTPPasswordMgrWithDefaultRealm()
        mgr.add_password(None, self.base, username, password)
        self.opener = urllib.request.build_opener(urllib.request.ProxyHandler({}),
                                                  urllib.request.HTTPDigestAuthHandler(mgr))

    def call(self, service, action, args=None):
        """One authenticated Get action. Only allowlisted (service, action) pairs are sent."""
        if (service, action) not in (('DeviceInfo', 'GetInfo'), ('Hosts', 'GetHostNumberOfEntries'),
                                     ('WANIPConnection', 'GetStatusInfo'),
                                     ('WLANConfiguration', 'GetTotalAssociations')):
            raise FritzboxRouterBlocked('refusing non-read router call %s.%s' % (service, action))
        if args:
            raise FritzboxRouterBlocked('read calls take no arguments')
        body = ('<?xml version="1.0" encoding="utf-8"?>'
                '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/"'
                ' s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/"><s:Body>'
                '<u:%s xmlns:u="urn:dslforum-org:service:%s:1"/>'
                '</s:Body></s:Envelope>' % (action, service)).encode()
        req = urllib.request.Request(self.base + SERVICES[service], data=body, method='POST',
                                     headers={'Content-Type': 'text/xml; charset="utf-8"',
                                              'SOAPAction': '"urn:dslforum-org:service:%s:1#%s"' % (service, action)})
        try:
            with self.opener.open(req, timeout=self.timeout) as resp:
                raw = resp.read(MAX_BODY + 1)
        except urllib.error.HTTPError as e:
            e.close()
            if e.code in (401, 403):
                raise FritzboxRouterBlocked('router refused the TR-064 user/password') from None
            raise FritzboxRouterError('%s.%s: HTTP %d' % (service, action, e.code)) from None
        except (OSError, ValueError) as e:
            raise FritzboxRouterError('%s.%s failed: %s' % (service, action, e)) from None
        if len(raw) > MAX_BODY:
            raise FritzboxRouterError('%s.%s answered too much' % (service, action))
        try:
            doc = ET.fromstring(raw)
        except ET.ParseError:
            raise FritzboxRouterError('%s.%s: not XML' % (service, action)) from None
        fault = _find(doc, 'Fault', 'faultcode', 'faultstring')
        if fault is not None:
            raise FritzboxRouterError('%s.%s refused: %s' % (service, action, (_find(doc, 'faultstring') or fault).text or '?'))
        return doc

    @staticmethod
    def _text(doc, *names):
        el = _find(doc, *names)
        return el.text.strip() if el is not None and el.text else None

    def read(self):
        info = self.call('DeviceInfo', 'GetInfo')      # required: proves an authenticated link
        uptime = self._text(info, 'NewUpTime')
        try:
            uptime = int(uptime)
        except (TypeError, ValueError):
            raise FritzboxRouterError('unrecognized uptime %r' % (uptime,)) from None
        state = {'uptime': max(0, uptime)}
        model = self._text(info, 'NewModelName')
        if model:
            state['model'] = model[:48]
        firmware = self._text(info, 'NewSoftwareVersion')
        if firmware:
            state['firmware'] = firmware[:32]

        def optional(service, action):
            try:
                return self.call(service, action)
            except (FritzboxRouterError, FritzboxRouterBlocked):
                return None

        wan = optional('WANIPConnection', 'GetStatusInfo')
        if wan is not None:
            status = self._text(wan, 'NewConnectionStatus') or ''
            state['wan'] = 'up' if status.lower() == 'connected' else 'down'
        hosts = optional('Hosts', 'GetHostNumberOfEntries')
        if hosts is not None:
            try:
                state['hosts'] = max(0, int(self._text(hosts, 'NewHostNumberOfEntries') or ''))
            except (TypeError, ValueError):
                pass
        wifi = optional('WLANConfiguration', 'GetTotalAssociations')
        if wifi is not None:
            try:
                state['wifi_clients'] = max(0, int(self._text(wifi, 'NewTotalAssociations') or ''))
            except (TypeError, ValueError):
                pass
        return state

    def write(self, name, value):
        raise FritzboxRouterBlocked(POLICY[('*', '*')])

    def command(self, name, value=None):
        raise FritzboxRouterBlocked(POLICY[('*', '*')])


def _refusal(name, value):
    return POLICY.get((name, value)) or POLICY.get((name, '*')) or POLICY.get(('*', '*'))


class FritzboxRouter:
    def __init__(self, transport):
        self.transport = transport
        self._before = {}

    def facts(self):
        state = self.transport.read()
        return [{'name': k, 'value': state[k], 'unit': unit} for k, unit in READ.items() if k in state]

    def set_reversible(self, name, value):
        reason = _refusal(name, value)
        if reason:
            raise FritzboxRouterBlocked(reason)
        if name not in WRITABLE or value not in WRITABLE[name]:
            raise FritzboxRouterBlocked('%s=%r is not an allowed setting' % (name, value))
        if name in self._before:
            raise FritzboxRouterBlocked('this setting has a pending Undo; undo it before changing it again')
        before = self.transport.read()
        if name not in before:
            raise FritzboxRouterBlocked('the device does not report %s' % name)
        self.transport.write(name, value)
        after = self.transport.read().get(name)
        verified = after == value
        if verified:
            self._before[name] = before[name]
        return {'setting': name, 'before': before[name], 'after': after, 'verified': verified, 'reversible': True}

    def undo(self, name):
        if name not in self._before:
            raise FritzboxRouterBlocked('nothing to undo for %s' % name)
        target = self._before[name]
        self.transport.write(name, target)
        now = self.transport.read().get(name)
        if now == target:
            self._before.pop(name)
        return {'setting': name, 'restored': now, 'exact': now == target}

    def command(self, name, value=None):
        reason = _refusal(name, value)
        if reason:
            raise FritzboxRouterBlocked(reason)
        if name not in COMMANDS or (COMMANDS[name] is None and value is not None) or (COMMANDS[name] is not None and value not in COMMANDS[name]):
            raise FritzboxRouterBlocked('%s is not an allowed command' % name)
        self.transport.command(name, value)
        # Momentary commands leave no lasting state to read back: reported as executed, never as verified.
        return {'command': name, 'value': value, 'verified': None, 'reversible': False}
